x = 5
if x == 5:
    print('Five')
else:
    print('Not Five')

x = 10
if x < 5:
    print('Less than 5')
elif x == 10:
    print('Ten')
else:
    print('More than 5')

x = 3
if x > 0:
    print('Positive')
elif x == 0:
    print('Zero')
else:
    print('Negative')

x = 8
if x < 5:
    print('Hello')
elif x == 8:
    print('World')
else:
    print('Test')

x = 20
if x <= 20:
    print('Twenty or less')
else:
    print('More than twenty')

day = 'Saturday'
if day == 'Monday':
    print('Start of the week')
elif day == 'Saturday':
    print('Weekend')
else:
    print('Midweek')

score = 85
if score >= 90:
    print('A')
elif score >= 80:
    print('B')
elif score >= 70:
    print('C')
else:
    print('D')

num = 7
if num % 2 == 0:
    print('Even')
elif num % 3 == 0:
    print('Divisible by 3')
else:
    print('Odd')

age = 17
if age < 18:
    print('Minor')
elif age < 65:
    print('Adult')
else:
    print('Senior')
if age == 17:
    print('Teenager')
